python3 -c "
import tempfile
import os

# Check what's in temp now
for d in os.listdir('/tmp'):
    if 'code_backup' in d:
        path = os.path.join('/tmp', d)
        print(f'{path}')
        for root, dirs, files in os.walk(path):
            for f in files:
                print(f'  {os.path.join(root, f)}')
